469	/** Groups a feed page by calendar day, newest day first. */
470	export function groupByDay(
471	  events: readonly ActivityEvent[],
472	): readonly ActivityGroup[] {
473	  const byDay = new Map<string, ActivityEvent[]>();
474	
475	  for (const event of events) {
476	    const day = event.occurredAt.slice(0, 10);
477	    const bucket = byDay.get(day) ?? [];
478	    bucket.push(event);
479	    byDay.set(day, bucket);
480	  }
481	
482	  return [...byDay.entries()]
483	    .sort(([a], [b]) => (a < b ? 1 : -1))
484	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
485	}
