668	export async function listActivity(
669	  input: ActivityFilterInput,
670	): Promise<Page<ActivityEvent>> {
671	  const db = getDb();
672	  const sort = {
673	    sortColumn: activityEvents.occurredAt,
674	    idColumn: activityEvents.id,
675	  };
676	
677	  const filters = compact(
678	    orgPredicate(activityEvents.orgId, input.orgId),
679	    input.action === undefined || input.action.length === 0
680	      ? undefined
681	      : inArray(activityEvents.action, [...input.action]),
682	    input.actorId === undefined
683	      ? undefined
684	      : eq(activityEvents.actorId, input.actorId),
685	    input.projectId === undefined
686	      ? undefined
687	      : eq(activityEvents.projectId, input.projectId),
688	    input.subjectKind === undefined
689	      ? undefined
690	      : eq(activityEvents.subjectKind, input.subjectKind),
691	    input.since === undefined
692	      ? undefined
693	      : gte(activityEvents.occurredAt, input.since),
694	    input.until === undefined
695	      ? undefined
696	      : lte(activityEvents.occurredAt, input.until),
697	  );
698	
699	  const total = db
700	    .select({ value: count() })
701	    .from(activityEvents)
702	    .where(and(...filters))
703	    .get();
704	
705	  const rows = db
706	    .select()
707	    .from(activityEvents)
708	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
709	    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
710	    .limit(probeLimit(input.limit))
711	    .all();
712	
713	  return toPage(
714	    rows,
715	    input.limit,
716	    total?.value ?? 0,
717	    toActivityEvent,
718	    (row) => ({ id: row.id, sortValue: row.occurredAt }),
719	  );
720	}
