786	/** Filters an in-memory collection according to an `ArchiveScope`. */
787	export function applyArchiveScope<T extends SoftDeletable>(
788	  rows: readonly T[],
789	  scope: ArchiveScope = {},
790	): readonly T[] {
791	  return scope.includeArchived === true ? rows : rows.filter(isLive);
792	}
793	
794	/** True when the repository should add the `archived_at IS NULL` predicate. */
