938	/** Same decision as `can()`, but reports why — used by the settings UI. */
939	export function explain(
940	  actor: Actor,
941	  action: PermissionAction,
942	  resource: PermissionResource,
943	): PermissionDecision {
944	  const base = { action, resourceKind: resource.kind } as const;
945	
946	  if (actor.orgId !== resource.orgId) {
947	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
948	  }
949	
950	  if (actor.isPlatformStaff === true) {
951	    return { ...base, allowed: true, reason: "granted_by_staff" };
952	  }
953	
954	  const required = ROLE_MATRIX[action];
955	  if (required === undefined) {
956	    return { ...base, allowed: false, reason: "denied_unknown_action" };
957	  }
958	
959	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
960	    return { ...base, allowed: true, reason: "granted_by_role" };
961	  }
962	
963	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
964	    return { ...base, allowed: true, reason: "granted_by_ownership" };
965	  }
966	
967	  return { ...base, allowed: false, reason: "denied_by_role" };
968	}
