768	/**
769	 * Soft-delete conventions.
770	 *
771	 * Issues, projects and comments are never physically removed — they get an
772	 * `archived_at` timestamp. Repositories must express "live rows only" through
773	 * these helpers so the predicate stays in one place; a raw
774	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
775	 * drift this module prevents.
776	 */
777	
778	export function isArchived(row: SoftDeletable): boolean {
779	  return row.archivedAt !== null;
780	}
781	
782	export function isLive(row: SoftDeletable): boolean {
783	  return row.archivedAt === null;
784	}
785	
786	/** Filters an in-memory collection according to an `ArchiveScope`. */
787	export function applyArchiveScope<T extends SoftDeletable>(
788	  rows: readonly T[],
789	  scope: ArchiveScope = {},
790	): readonly T[] {
791	  return scope.includeArchived === true ? rows : rows.filter(isLive);
792	}
793	
794	/** True when the repository should add the `archived_at IS NULL` predicate. */
795	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
796	  return scope.includeArchived !== true;
797	}
