799	/** The column patch that archives a row. */
800	export function archivePatch(now: Date = new Date()): {
801	  archivedAt: IsoTimestamp;
802	  updatedAt: IsoTimestamp;
803	} {
804	  const stamp = toIsoTimestamp(now);
805	  return { archivedAt: stamp, updatedAt: stamp };
806	}
807	
808	/** The column patch that restores an archived row. */
809	export function restorePatch(now: Date = new Date()): {
810	  archivedAt: null;
811	  updatedAt: IsoTimestamp;
812	} {
813	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
814	}
