843	/**
844	 * The single authorization entry point for Taskflow.
845	 *
846	 * Every Server Action, service method, Route Handler and permission-sensitive
847	 * UI component funnels through `can()`. Nothing else may branch on
848	 * `actor.role` directly — if you find yourself writing `role === "admin"`,
849	 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
850	 *
851	 * Decision order:
852	 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
853	 *   2. platform staff bypass
854	 *   3. role matrix lookup
855	 *   4. ownership escalations (authors edit their own issues/comments)
856	 */
857	
858	/** Minimum role required for each action, before ownership escalations. */
859	export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
860	  "org:read": "viewer",
861	  "org:update": "admin",
862	  "org:delete": "owner",
863	  "org:manage_billing": "owner",
864	  "org:manage_flags": "admin",
865	  "member:read": "viewer",
866	  "member:invite": "admin",
867	  "member:update_role": "admin",
868	  "member:remove": "admin",
869	  "project:create": "member",
870	  "project:read": "viewer",
871	  "project:update": "member",
872	  "project:archive": "admin",
873	  "project:delete": "owner",
874	  "issue:create": "member",
875	  "issue:read": "viewer",
876	  "issue:update": "member",
877	  "issue:assign": "member",
878	  "issue:archive": "member",
879	  "issue:delete": "admin",
880	  "comment:create": "member",
881	  "comment:read": "viewer",
882	  "comment:update": "member",
883	  "comment:delete": "admin",
884	  "activity:read": "member",
885	  "activity:export": "admin",
886	  "notification:read": "viewer",
887	  "notification:manage": "viewer",
888	  "webhook:manage": "admin",
889	};
890	
891	/** Actions an actor may perform on their own content regardless of role rank. */
892	const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
893	  "issue:update": true,
894	  "issue:archive": true,
895	  "comment:update": true,
896	  "comment:delete": true,
897	  "notification:manage": true,
898	};
