900	function isOwnedByActor(
901	  actor: Actor,
902	  resource: PermissionResource,
903	): boolean {
904	  switch (resource.kind) {
905	    case "issue":
906	      return (
907	        resource.authorId === actor.userId ||
908	        resource.assigneeId === actor.userId
909	      );
910	    case "comment":
911	      return resource.authorId === actor.userId;
912	    case "project":
913	      return resource.leadId === actor.userId;
914	    case "notification":
915	      return resource.recipientId === actor.userId;
916	    case "member":
917	      return resource.targetUserId === actor.userId;
918	    default:
919	      return false;
920	  }
921	}
922	
923	/**
924	 * Answers "may this actor perform this action on this resource?".
925	 *
926	 * @param actor    the authenticated principal, always scoped to one org
927	 * @param action   a member of the closed `PermissionAction` vocabulary
928	 * @param resource the object being acted on, discriminated on `kind`
929	 */
930	export function can(
931	  actor: Actor,
932	  action: PermissionAction,
933	  resource: PermissionResource,
934	): boolean {
935	  return explain(actor, action, resource).allowed;
936	}
937	
938	/** Same decision as `can()`, but reports why — used by the settings UI. */
939	export function explain(
940	  actor: Actor,
941	  action: PermissionAction,
942	  resource: PermissionResource,
943	): PermissionDecision {
944	  const base = { action, resourceKind: resource.kind } as const;
945	
946	  if (actor.orgId !== resource.orgId) {
947	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
948	  }
949	
950	  if (actor.isPlatformStaff === true) {
951	    return { ...base, allowed: true, reason: "granted_by_staff" };
952	  }
953	
954	  const required = ROLE_MATRIX[action];
955	  if (required === undefined) {
956	    return { ...base, allowed: false, reason: "denied_unknown_action" };
957	  }
958	
959	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
960	    return { ...base, allowed: true, reason: "granted_by_role" };
961	  }
962	
963	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
964	    return { ...base, allowed: true, reason: "granted_by_ownership" };
965	  }
966	
967	  return { ...base, allowed: false, reason: "denied_by_role" };
968	}
