970	/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
971	export class PermissionDeniedError extends Error {
972	  readonly code = "forbidden" as const;
973	
974	  constructor(
975	    readonly action: PermissionAction,
976	    readonly decision: PermissionDecision,
977	  ) {
978	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
979	    this.name = "PermissionDeniedError";
980	  }
981	}
982	
983	/** Throwing variant of `can()` for service-layer guard clauses. */
984	export function assertCan(
985	  actor: Actor,
986	  action: PermissionAction,
987	  resource: PermissionResource,
988	): void {
989	  const decision = explain(actor, action, resource);
990	  if (!decision.allowed) {
991	    throw new PermissionDeniedError(action, decision);
992	  }
993	}
994	
995	/** Bulk evaluation used by navigation and toolbar components. */
996	export function canAll(
997	  actor: Actor,
998	  actions: readonly PermissionAction[],
999	  resource: PermissionResource,
1000	): boolean {
1001	  return actions.every((action) => can(actor, action, resource));
1002	}
