/**
 * Owners who can actually act — live and not suspended — optionally leaving
 * one member out. This is the number the last-owner invariant is stated in.
 */
export async function countActiveOwners(
  orgId: OrgId,
  exceptMemberId?: MemberId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.role, "owner"),
        eq(members.status, "active"),
        liveMemberPredicate(),
        exceptMemberId === undefined ? undefined : ne(members.id, exceptMemberId),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Which of `userIds` are currently suspended in this org. Removed members are
 * archived and therefore never reported here.
 */
export async function listSuspendedUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "suspended"),
        liveMemberPredicate(),
        inArray(members.userId, [...new Set(userIds)]),
      ),
    )
    .all();

  return new Set(rows.map((row) => row.userId as UserId));
}

export async function isUserSuspended(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  return (await listSuspendedUserIds(orgId, [userId])).has(userId);
}

