import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as ms from "@/server/services/member-service";
import * as issues from "@/server/services/issue-service";
import * as comments from "@/server/services/comment-service";
import { notify } from "@/server/services/notification-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());
it("suspension flow", async () => {
  const t = await createTenant("susp", "growth");
  const o = t.org.id;
  const m = (await memberRepo.findMember(o, t.userIds.member))!;
  const own = (await memberRepo.findMember(o, t.userIds.owner))!;
  const events: string[] = [];
  subscribe("member.suspended", () => { events.push("s"); });
  subscribe("member.reinstated", () => { events.push("r"); });
  await expect(ms.suspendMember(t.actors.admin, { orgId: o, memberId: own.id })).rejects.toThrow();
  await expect(ms.suspendMember(t.actors.owner, { orgId: o, memberId: own.id })).rejects.toThrow();
  await expect(ms.suspendMember(t.actors.member, { orgId: o, memberId: m.id })).rejects.toThrow();
  expect(events).toEqual([]);
  const s = await ms.suspendMember(t.actors.admin, { orgId: o, memberId: m.id });
  expect(s.status).toBe("suspended");
  await ms.suspendMember(t.actors.admin, { orgId: o, memberId: m.id });
  expect(events).toEqual(["s"]);
  expect(await ms.resolveActor(t.userIds.member, o)).toBeNull();
  expect(await orgRepo.listOrgsForUser(t.userIds.member)).toHaveLength(0);
  expect(await memberRepo.countActiveMembers(o)).toBe(4);
  expect((await usageRepo.recomputeUsage(o)).seatsUsed).toBe(4);
  expect(await notify(o, "issue_assigned", [t.userIds.member], { title: "a", body: "b", href: "/", actorId: null })).toHaveLength(0);
  await expect(issues.createIssue(t.actors.owner, issueInput(o, t.project.id, { assigneeId: t.userIds.member }))).rejects.toBeInstanceOf(ms.MemberSuspendedError);
  const issue = await issues.createIssue(t.actors.owner, issueInput(o, t.project.id));
  await expect(issues.assignIssue(t.actors.owner, { orgId: o, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toBeInstanceOf(ms.MemberSuspendedError);
  const c = await comments.createComment(t.actors.owner, { orgId: o, issueId: issue.id, body: "hi @member and @admin", parentId: null, mentionedUserIds: [t.userIds.member] } as never);
  expect(c.mentionedUserIds).toEqual([t.userIds.admin]);
  const list = await ms.listMembers(t.actors.owner, { orgId: o, limit: 50, cursor: null } as never);
  expect(list.items.find((x) => x.id === m.id)?.status).toBe("suspended");
  const r = await ms.reinstateMember(t.actors.owner, { orgId: o, memberId: m.id });
  expect(r.status).toBe("active");
  expect(events).toEqual(["s", "r"]);
  expect(await ms.resolveActor(t.userIds.member, o)).not.toBeNull();
  const audit = await activityRepo.listActivityForSubject(o, "member", m.id);
  expect(audit.map((a) => a.action).sort()).toEqual(["member.reinstated", "member.suspended"]);
  await ms.removeMember(t.actors.owner, { orgId: o, memberId: m.id });
  await expect(ms.suspendMember(t.actors.owner, { orgId: o, memberId: m.id })).rejects.toMatchObject({ code: "not_found" });
  expect(await memberRepo.countActiveMembers(o)).toBe(3);
});
EOF
